package app.oncare.personal;
import android.app.*;
import android.content.*;
import android.os.*;
import android.widget.*;
import org.json.*;

public final class SleepSoundActivity extends GalaxyActivity {
    final Handler handler=new Handler(Looper.getMainLooper());LinearLayout body;TextView state;Spinner sensitivity;double threshold=-35;ScrollView currentScroll;boolean lastRunning;long lastRender;boolean research=false;
    final Runnable refresh=new Runnable(){public void run(){if(lastRunning!=SleepSoundService.running||SystemClock.elapsedRealtime()-lastRender>=60000)render();else if(state!=null)state.setText(SleepSoundService.status);handler.postDelayed(this,5000);}};
    @Override public void onCreate(Bundle saved){super.onCreate(saved);if(saved!=null){threshold=saved.getDouble("threshold",-35);research=saved.getBoolean("research",false);}render();}
    @Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putDouble("threshold",threshold);state.putBoolean("research",research);}
    TextView text(String value,int size){TextView t=new TextView(this);t.setText(value);t.setTextColor(foreground());t.setTextSize(size);t.setPadding(20,16,20,16);return t;}
    void button(String title,Runnable action){Button b=new Button(this);b.setText(title);b.setOnClickListener(v->action.run());body.addView(b);}
    void render(){
        int previousY=currentScroll==null?0:currentScroll.getScrollY();lastRunning=SleepSoundService.running;lastRender=SystemClock.elapsedRealtime();ScrollView scroll=new ScrollView(this);currentScroll=scroll;body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(24,40,24,32);body.setBackgroundColor(background());scroll.addView(body);body.addView(text("수면 소리 기록",28));body.addView(text("원음·대화는 저장·전송하지 않아요. 기본 측정은 1분 단위 소리 크기를 남겨요. 실제 수면 시간·수면 단계·코골이·무호흡을 판별하지 않아요. 주변 소음과 다른 사람의 소리도 포함될 수 있어요.",16));body.addView(text("휴대폰을 침구로 덮지 말고 안전한 곳에 두세요. 충전 상태를 확인하고 같은 공간 사람의 동의를 받아주세요. 측정 중 알림이 표시됩니다.",14));
        sensitivity=new Spinner(this);sensitivity.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"민감 -45 dBFS","기본 -35 dBFS","둔감 -25 dBFS"}));sensitivity.setSelection(threshold==-45?0:threshold==-25?2:1);sensitivity.setEnabled(!SleepSoundService.running);body.addView(sensitivity);sensitivity.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,android.view.View v,int index,long id){threshold=new double[]{-45,-35,-25}[index];}});
        body.addView(text("dBFS는 상대 신호 크기이며 소음계 dB가 아닙니다.",13));state=text(SleepSoundService.status,15);body.addView(state);
        Switch researchSwitch=new Switch(this);researchSwitch.setText("연구용 호흡 후보 분석");researchSwitch.setChecked(research);researchSwitch.setEnabled(!SleepSoundService.running&&SleepResearch.available(this));researchSwitch.setOnCheckedChangeListener((button,checked)->research=checked);body.addView(researchSwitch);
        body.addView(text(SleepResearch.available(this)?"켜면 30초 음향을 메모리에서만 분석하고 후보 구간 수만 남겨요. 2명 평가에서 균형 정확도 62.5%인 초기 모델로, 건강 판단·무호흡 경고에 사용할 수 없어요.":"연구 모델 미포함 빌드예요. 소리 크기 기록은 사용할 수 있어요.",13));

        if(SleepSoundService.running)button("측정 종료",()->startService(new Intent(this,SleepSoundService.class).setAction("stop")));else button("마이크 소리 측정 시작",this::requestStart);
        JSONArray history=SleepSoundService.history(this);CareUpgradeUI.sleep(this,body,history);for(int i=0;i<Math.min(7,history.length());i++){JSONObject session=history.optJSONObject(i);if(session==null)continue;JSONArray bins=session.optJSONArray("bins");double minutes=0,loud=0;for(int j=0;bins!=null&&j<Math.min(480,bins.length());j++){JSONObject bin=bins.optJSONObject(j);if(bin==null)continue;double seconds=bin.optDouble("seconds",0);if(!Double.isFinite(seconds)||seconds<=0||seconds>65)continue;minutes+=seconds/60;if(bin.optDouble("rms",-120)>=session.optDouble("threshold",-35))loud+=seconds/60;}body.addView(text(android.text.format.DateFormat.format("M월 d일 HH:mm",session.optLong("started"))+"\n측정 "+(int)minutes+"분 · 기준 이상 "+(int)loud+"분\n"+(session.has("ended")?session.optString("reason"):SleepSoundService.running&&session.optLong("started")==SleepSoundService.activeStarted?"측정 중":"앱 종료·중단 후 복구된 요약"),17));}
        
        for(int i=0;i<Math.min(7,history.length());i++){JSONObject item=history.optJSONObject(i);JSONObject summary=item==null?null:item.optJSONObject("research");if(summary!=null){int n=Math.max(0,Math.min(960,summary.optInt("analyzed"))),c=Math.max(0,Math.min(n,summary.optInt("candidates"))),skip=Math.max(0,Math.min(960,summary.optInt("skipped")));body.addView(text(android.text.format.DateFormat.format("M월 d일 HH:mm",item.optLong("started"))+" · 연구용 후보 구간 "+c+" / 분석 "+n+" · 판정 보류 "+skip+"\n30초 구간 기준이며 무호흡 횟수·수면 단계·정상 판정이 아닙니다.",14));}}
        body.addView(text("최근 7회·회당 최대 약 8시간. 통화·마이크 변경·앱 강제 종료·기기 절전 정책으로 중단될 수 있으며 자동 재시작하지 않아요. 측정 시간은 수면 시간이 아닙니다.",13));if(!SleepSoundService.running)button("소리 요약 전체 삭제",()->new AlertDialog.Builder(this).setTitle("소리 요약을 모두 삭제할까요?").setNegativeButton("취소",null).setPositiveButton("삭제",(d,w)->{synchronized(SleepSoundService.class){new android.util.AtomicFile(new java.io.File(getNoBackupFilesDir(),"sleep-sound-v1.json")).delete();}render();}).show());button("닫기",this::finish);setContentView(scroll);scroll.post(()->scroll.scrollTo(0,previousY));
    }
    void requestStart(){if(checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=android.content.pm.PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.RECORD_AUDIO},6422);return;}if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},6423);return;}try{Intent intent=new Intent(this,SleepSoundService.class).putExtra("threshold",threshold).putExtra("research",research);startForegroundService(intent);state.setText("마이크 준비 중…");}catch(Exception e){state.setText("측정을 시작하지 못했어요. 앱을 화면에 연 상태에서 다시 시도해주세요.");}}
    @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] grants){super.onRequestPermissionsResult(request,permissions,grants);if(grants.length>0&&grants[0]==android.content.pm.PackageManager.PERMISSION_GRANTED)requestStart();else state.setText("측정하려면 마이크·알림 권한을 허용해주세요. 자동 시작하지 않았어요.");}
    @Override protected void onResume(){super.onResume();handler.post(refresh);}
    @Override protected void onPause(){handler.removeCallbacks(refresh);super.onPause();}
}
